mapper.select:
SELECT t.TRADE_ID tradeId,/**交易编号**/ null outTradeId, /*外部成交编号*/ deal.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_MARKET_ID oAssetId,/**转出证券代码**/ zc.FINPROD_ABBR oAssetAbbr,/**转出证券代码**/ tfpb.FINPROD_ID cAssetId,/**转入证券代码**/ fp.FINPROD_ABBR cAssetAbbr,/**转入证券名称**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE settdateDate,/**交割日期**/ t.INV_AIM invAim,/**会计分类**/ t.SHARE_AMT oTradeNum,/**成交数量**/ t.trade_amt oTradeAmt,/**全价总额**/ tfpb.SHARE_AMT cTradeNum,/**成交数量**/ tfpb.PRIN_AMT cTradeAmt,/**全价总额**/ t.CCY ccy,/**币种**/ stl.SETTLE_AMT settleAmt,/**结算金额**/ stl.MY_ACCT_NO acctNo/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID LEFT JOIN TRD_FIN_PRODUCT_BARTER tfpb ON tfpb.TRADE_ID = t.TRADE_ID LEFT JOIN FIN_PRODUCT fp ON tfpb.FINPROD_ID = fp.FINPROD_ID where t.BUSI_TYPE in('02','06','07') AND t.PS in('T49','T64','T63')
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_MARKET_ID IN
#{asset}
and tfpb.FINPROD_ID IN
#{cAssetId}
and t.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
and t.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND t.PS IN
#{ps}
order by t.TRADE_ID desc

mapper.delete:
DELETE FROM BOK_DETAIL_ID
WHERE BOOKSET_ID = #{booksetId}
  and TRADE_ID = #{tradeId}
